{"file_path":"src/sim.js","content":"// Bucket tokens are stored scaled by `per`, so refill is exact integer math.
function fresh(p, tick) {
  return p.kind === 'bucket'
    ? { units: p.capacity * p.per, last: tick }
    : { ticks: [] }
}

function advance(p, st, tick) {
  if (p.kind === 'bucket') {
    st.units += p.refill * (tick - st.last)
    st.last = tick
    const cap = p.capacity * p.per
    if (st.units > cap) st.units = cap
  } else {
    const cut = tick - p.span
    st.ticks = st.ticks.filter((t) => t > cut)
  }
}

function allows(p, st) {
  return p.kind === 'bucket' ? st.units >= p.per : BigInt(st.ticks.length) < p.limit
}

function record(p, st, tick) {
  if (p.kind === 'bucket') st.units -= p.per
  else st.ticks.push(tick)
}

export function simulate({ routes, events }, mode) {
  const prefixes = [...routes.keys()]
  const states = new Map()
  const stats = new Map()
  const lines = []
  let allowed = 0
  let denied = 0

  for (const { tick, key } of events) {
    let best = null
    for (const pre of prefixes) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let refused = null
    if (best !== null) {
      const route = routes.get(best)
      const sts = route.map((p) => {
        const id = `${p.name}\0${key}`
        if (!states.has(id)) states.set(id, fresh(p, tick))
        return states.get(id)
      })
      route.forEach((p, i) => advance(p, sts[i], tick))
      const idx = route.findIndex((p, i) => !allows(p, sts[i]))
      if (idx >= 0) refused = route[idx].name
      else route.forEach((p, i) => record(p, sts[i], tick))
    }
    const s = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, s)
    if (refused === null) { s.a++; allowed++ } else { s.d++; denied++ }
    lines.push(refused === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${refused}`)
  }

  if (mode === 'replay') return lines.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') +
    `total allowed=${allowed} denied=${denied}\n`
}
"}

