/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { simulate } from './sim.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

let out
try {
  out = simulate(parse(readFileSync(0, 'utf8')), mode)
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
"}

